mapper.select:
SELECT v.post_type, v.post_id, p.title, p.status, p.author_id, COUNT(*) AS views FROM post_view_logs v JOIN (SELECT 'review' AS kind, id, title, status, author_id FROM reviews WHERE deleted_at IS NULL UNION ALL SELECT 'interview', id, title, status, author_id FROM interviews WHERE deleted_at IS NULL UNION ALL SELECT 'project', id, service_name, status, author_id FROM projects WHERE deleted_at IS NULL) p ON p.kind = v.post_type AND p.id = v.post_id
v.viewed_on BETWEEN #{from} AND #{to}
GROUP BY v.post_type, v.post_id, p.title, p.status, p.author_id ORDER BY views DESC, v.post_type, v.post_id LIMIT #{limit}
